packagev3.Artifact:
Artifact struct {
	Path	string	`json:"path"`
	SHA256	string	`json:"sha256"`
}

packagev3.BrokerOptions:
BrokerOptions struct {
	Execution	ExecutionOptions

	Seed	authority.Authority

	Credentials	map[string]authority.Binding
	Now		time.Time
}

packagev3.ExecutionOptions:
ExecutionOptions struct {
	Worker			WorkerIdentity
	RuntimeAdmission	RuntimeAdmission
}

packagev3.Finding:
Finding struct {
	Code	string	`json:"code"`
	Path	string	`json:"path"`
	Outcome	string	`json:"outcome"`
}

packagev3.RuntimeAdmissionRequest:
RuntimeAdmissionRequest struct {
	RuntimeRevision	string
	WorkflowYAML	[]byte
	DataJSON	[]byte
	Sources		map[string][]byte
}

packagev3.Source:
Source struct {
	ID		string		`json:"id"`
	Kind		string		`json:"kind"`
	Artifact	Artifact	`json:"artifact"`
}

packagev3.WorkerIdentity:
WorkerIdentity struct {
	BinarySHA256	string	`json:"binary_sha256"`
	ClosureSHA256	string	`json:"closure_sha256"`
	RuntimeRevision	string	`json:"runtime_revision"`
}
